// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint v) public {
        vm.assume(_tos.length > 0);
        for (uint i = 0; i < _tos.length; i++) {
            vm.assume(_tos[i] != address(0));
        }
        vm.assume(v > 0);
        bool success;
        bytes memory data = abi.encodeWithSignature("transferFrom(address,address,uint256)", from, _tos[0], v);
        (success, ) = caddress.call(data);
        vm.assume(success);
        success = false;
        try c.transfer(from, caddress, _tos, v) {
            success = true;
        } catch {
            success = false;
        }
        assertTrue(success, "transfer should not revert when inner calls succeed");
    }
}

